let doublePulseCount = 0;

export function doublePulse() {
    doublePulseCount++;
}
export function _reset() {
    doublePulseCount = 0;
}
export function _getDoublePulseCount() {
    return doublePulseCount;
}

const Vibes = {
    doublePulse,
    _reset,
    _getDoublePulseCount
};

export default Vibes;
